BEGIN IMMEDIATE;

CREATE TABLE IF NOT EXISTS tradition_access_policies (
    id TEXT PRIMARY KEY,
    entity_id TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE,
    source_id TEXT REFERENCES sources(id),
    authority_name TEXT NOT NULL,
    community_context TEXT,
    access_level TEXT NOT NULL CHECK(access_level IN ('PUBLIC_CONTEXT','ATTRIBUTION_REQUIRED','PERMISSION_REQUIRED','DO_NOT_COLLECT')),
    permitted_scope TEXT NOT NULL,
    prohibited_scope TEXT NOT NULL,
    attribution_requirement TEXT,
    permission_contact_or_process TEXT,
    policy_basis TEXT NOT NULL,
    reviewed_at TEXT NOT NULL,
    notes TEXT
);
CREATE INDEX IF NOT EXISTS idx_tradition_access_entity ON tradition_access_policies(entity_id);
CREATE INDEX IF NOT EXISTS idx_tradition_access_level ON tradition_access_policies(access_level);

INSERT OR IGNORE INTO entities(id,canonical_name,name_zh,original_name,transliteration,primary_type,primary_civilization_id,primary_region_id,historical_period,description,research_status,evidence_status,record_version,metadata_json,created_at,updated_at) VALUES
('concept.yoruba.living_tradition_access','Yoruba living-tradition access governance','约鲁巴活态传统访问治理',NULL,NULL,'CONCEPT','civ.yoruba','region.west_africa','Contemporary ethical research governance','连接 Ifá、Ṣàngó 公开资料与权限规则；权限记录不是神话事实，也不授予采集秘密内容的许可。 / Governance layer for public, attributed, permission-required and prohibited collection scopes.','PARTIAL','SOURCE_BACKED',1,'{"governance_layer":true,"permission_is_not_implied_by_public_url":true}','2026-08-27T16:00:00Z','2026-08-27T16:00:00Z'),
('concept.maori.iwi_variant_scope','Māori iwi/hapū variant and attribution scope','毛利 iwi／hapū 版本与署名范围',NULL,NULL,'CONCEPT','civ.maori','region.oceania','Living traditions and modern curated publication','记录各部族版本差异、作者署名与权限边界；不制造单一“毛利标准版”。 / Governance and comparison layer preserving iwi/hapū variation and attribution.','PARTIAL','SOURCE_BACKED',1,'{"single_standard_version":false,"community_attribution_required":true}','2026-08-27T16:00:00Z','2026-08-27T16:00:00Z');
