INSERT OR IGNORE INTO names(id,entity_id,name_text,normalized_text,language_id,script_name,name_type,is_preferred,source_id,notes) VALUES
('name.v0230.yoruba_access','concept.yoruba.living_tradition_access','Yoruba living-tradition access governance','yoruba living tradition access governance','lang.en','Latin','DESCRIPTIVE',1,'source.yoruba.ifa.unesco','Modern project-governance label.'),
('name.v0230.maori_scope','concept.maori.iwi_variant_scope','Māori iwi/hapū variant and attribution scope','maori iwi hapu variant attribution scope','lang.mai','Latin','DESCRIPTIVE',1,'source.maori.creation.teara','Modern project-governance label.');

INSERT OR IGNORE INTO tradition_access_policies(id,entity_id,source_id,authority_name,community_context,access_level,permitted_scope,prohibited_scope,attribution_requirement,permission_contact_or_process,policy_basis,reviewed_at,notes) VALUES
('policy.ifa.public_context','text.yoruba.ifa_corpus','source.yoruba.ifa.unesco','UNESCO ICH public registry and named Yoruba custodial communities','Ifá as a living Yoruba divination and oral-knowledge tradition','PUBLIC_CONTEXT','UNESCO public summary, safeguarding context and registry metadata','Full verse corpus, initiatory instruction, lineage-restricted interpretations and non-public ritual detail','Cite UNESCO and identify the public registry scope','Use named community/lineage authority for anything beyond the public page','Source scope plus project non-extraction rule','2026-08-27','A public URL does not make the whole tradition public domain.'),
('policy.ifa.restricted','text.yoruba.ifa_corpus','source.yoruba.ifa.unesco','Relevant Ifá lineage/community custodians','Lineage-specific, initiatory or non-public knowledge','DO_NOT_COLLECT','None in this public research pipeline','Secret verses, initiatory sequences, divination-client data, restricted ritual instructions and lineage-confidential interpretations','Not applicable because collection is prohibited','A separately authorized community-led project would be required; this database must not repurpose such permission','Precautionary community-governance rule','2026-08-27','Explicit hard stop for collection and storage.'),
('policy.sango.public_festival','festival.yoruba.sango_oyo','source.yoruba.sango_festival.unesco','Oyo Ṣàngó Festival communities and UNESCO ICH public registry','Publicly documented festival and safeguarding context','ATTRIBUTION_REQUIRED','Official public festival description, inscription decision and public safeguarding information','Non-public rites, restricted spaces, participant personal data and claims of authority not stated by custodians','Cite UNESCO record and name Oyo community context','Refer non-public questions to authorized Oyo institutions/custodians','Source terms and living-tradition attribution rule','2026-08-27','Public festival visibility does not erase ritual boundaries.'),
('policy.sango.restricted','festival.yoruba.sango_oyo','source.yoruba.sango_festival.unesco','Authorized Oyo custodians','Non-public ritual and interior community knowledge','PERMISSION_REQUIRED','Only material specifically released by an authorized custodian for the stated use','Secret or restricted rites, interior locations, unconsented participant data and generalized Yoruba-wide claims','Record named authority, scope and date of permission per claim','Obtain explicit purpose-specific permission before collection','Community authority and least-collection rule','2026-08-27','No permission is inferred from museum or UNESCO publication.'),
('policy.ose_sango.museum','artifact.yoruba.ose_sango','source.yoruba.ose_sango.met.1983_603_5','Metropolitan Museum of Art for object metadata; Yoruba custodians for living meaning','Museum object metadata and living religious context are separate authority layers','ATTRIBUTION_REQUIRED','Catalogue number, material, dimensions, custody and museum-published interpretation','Image reuse outside terms, secret ritual use or treating a museum object as exhaustive community authority','Cite catalogue and distinguish curator interpretation from community authority','Seek custodial authority for non-public living-practice claims','Museum catalogue scope plus living-tradition distinction','2026-08-27',NULL),
('policy.maori.teara_public','text.maori.creation_traditions','source.maori.creation.teara','Te Ahukaramū Charles Royal / Te Ara','Public, named, curated synthesis of Māori creation traditions','ATTRIBUTION_REQUIRED','Public text under stated CC BY-NC terms, with author and source attribution','Generalizing the synthesis as every iwi/hapū version; reusing non-text media without checking its terms','Attribute Te Ahukaramū Charles Royal and Te Ara; preserve page licence limits','Commercial reuse or non-text media requires the stated source process','Te Ara citation and licence notice','2026-08-27','Public synthesis explicitly says tribes have different versions.'),
('policy.maori.iwi_variants','text.maori.creation_traditions','source.maori.creation.teara','Relevant iwi/hapū authority for a named variant','Community-specific creation narratives and whakapapa','PERMISSION_REQUIRED','A public community-published account, or material supplied under explicit scoped permission','Unattributed pan-Māori synthesis, restricted whakapapa, sacred detail or reuse beyond consent','Name iwi/hapū, speaker/author, publication and permission scope','Obtain permission from the relevant authority for non-public or community-specific material','Community-specific attribution and variation rule','2026-08-27','Not all iwi share an Io tradition; variation is a first-class data property.'),
('policy.maori.restricted_whakapapa','text.maori.creation_traditions',NULL,'Relevant iwi/hapū and knowledge holders','Restricted whakapapa or sacred community knowledge','DO_NOT_COLLECT','None unless a future community-led system explicitly changes the storage model','Restricted genealogies, sacred knowledge and material whose publication status or authority is unclear','Not applicable because collection is prohibited by default','Do not solicit or store; refer to community authority','Precautionary Indigenous data-governance rule','2026-08-27','Default-deny for ambiguity.');

