('claim.v0230.ifa_public_registry','text.yoruba.ifa_corpus','PUBLICLY_CONTEXTUALIZED_BY',NULL,'UNESCO Intangible Cultural Heritage public registry','text','The project may retain the public UNESCO context for Ifá while applying stricter limits to non-public knowledge.','living_access.ifa','SUPPORTED',0.99,'HIGH','VERIFIED','HISTORICAL_REALITY','RITUAL_PRACTICE','Ifá public safeguarding context','current registry','This does not authorize corpus extraction.','2026-08-27T16:00:00Z'),
('claim.v0230.ifa_policy','text.yoruba.ifa_corpus','GOVERNED_BY','concept.yoruba.living_tradition_access',NULL,NULL,'The Ifá dossier is governed by explicit living-tradition access policies.','living_access.ifa','SUPPORTED',1.0,'HIGH','VERIFIED','SCHOLARLY_INTERPRETATION','SCHOLARLY_INTERPRETATION','Project governance','current',NULL,'2026-08-27T16:00:00Z'),
('claim.v0230.ifa_no_secret','concept.yoruba.living_tradition_access','PROHIBITS_COLLECTION_OF',NULL,'secret verses, initiatory instructions, divination-client data and lineage-restricted interpretations','text','The public research pipeline must not collect or store restricted Ifá knowledge.','living_access.ifa','SUPPORTED',1.0,'HIGH','VERIFIED','SCHOLARLY_INTERPRETATION','SCHOLARLY_INTERPRETATION','Project governance','current','Ethical access rule, not a description of the content.','2026-08-27T16:00:00Z'),
('claim.v0230.sango_registry','festival.yoruba.sango_oyo','PUBLICLY_CONTEXTUALIZED_BY',NULL,'UNESCO Intangible Cultural Heritage public registry and inscription decision','text','The public festival and safeguarding context may be recorded with attribution.','living_access.sango','SUPPORTED',0.99,'HIGH','VERIFIED','HISTORICAL_REALITY','RITUAL_PRACTICE','Oyo Ṣàngó Festival','current registry',NULL,'2026-08-27T16:00:00Z'),
('claim.v0230.sango_policy','festival.yoruba.sango_oyo','GOVERNED_BY','concept.yoruba.living_tradition_access',NULL,NULL,'The festival dossier uses public, attributed and permission-required access levels.','living_access.sango','SUPPORTED',1.0,'HIGH','VERIFIED','SCHOLARLY_INTERPRETATION','SCHOLARLY_INTERPRETATION','Project governance','current',NULL,'2026-08-27T16:00:00Z'),
('claim.v0230.sango_limit','concept.yoruba.living_tradition_access','REQUIRES_PERMISSION_FOR',NULL,'non-public rites, restricted spaces and participant-specific data','text','Non-public Ṣàngó material requires purpose-specific authority rather than inference from a public listing.','living_access.sango','SUPPORTED',1.0,'HIGH','VERIFIED','SCHOLARLY_INTERPRETATION','SCHOLARLY_INTERPRETATION','Project governance','current',NULL,'2026-08-27T16:00:00Z'),
('claim.v0230.maori_many','text.maori.creation_traditions','HAS_VARIANTS',NULL,'many traditions with tribe-specific versions and common themes','text','Te Ara states that Māori have many creation traditions and that tribes tell different versions.','living_access.maori','SUPPORTED',0.99,'HIGH','VERIFIED','IN_TRADITION','TEXTUAL_WITNESS','Te Ara public synthesis','published 2009','Attribute the named author; do not generalize as one standard text.','2026-08-27T16:00:00Z'),
('claim.v0230.maori_io','text.maori.creation_traditions','HAS_VARIANTS',NULL,'not all tribes have an Io tradition','text','The public synthesis explicitly notes that not all tribes have an Io tradition.','living_access.maori','SUPPORTED',0.99,'HIGH','VERIFIED','IN_TRADITION','TEXTUAL_WITNESS','Te Ara public synthesis','published 2009',NULL,'2026-08-27T16:00:00Z'),
('claim.v0230.maori_scope','concept.maori.iwi_variant_scope','DERIVED_FROM','text.maori.creation_traditions',NULL,NULL,'The governance node responds to the source’s explicit statement of tribal variation.','living_access.maori','SUPPORTED',0.99,'HIGH','VERIFIED','SCHOLARLY_INTERPRETATION','SCHOLARLY_INTERPRETATION','Project governance','current',NULL,'2026-08-27T16:00:00Z'),
('claim.v0230.maori_no_standard','concept.maori.iwi_variant_scope','PRESERVES_DISTINCTION',NULL,'iwi/hapū versions, named authorship, public licence and permission scope','text','The project does not construct a single canonical Māori creation version.','living_access.maori','SUPPORTED',1.0,'HIGH','VERIFIED','SCHOLARLY_INTERPRETATION','SCHOLARLY_INTERPRETATION','Project governance','current',NULL,'2026-08-27T16:00:00Z'),
('claim.v0230.maori_permission','concept.maori.iwi_variant_scope','REQUIRES_PERMISSION_FOR',NULL,'non-public community-specific narratives, restricted whakapapa and sacred detail','text','Community-specific non-public material is default-deny unless an appropriate authority grants scoped permission.','living_access.maori','SUPPORTED',1.0,'HIGH','VERIFIED','SCHOLARLY_INTERPRETATION','SCHOLARLY_INTERPRETATION','Project governance','current',NULL,'2026-08-27T16:00:00Z');

INSERT OR IGNORE INTO evidence(id,claim_id,source_id,source_location,evidence_type,direction,strength,research_notes)
SELECT 'evidence.'||substr(c.id,7),c.id,
 CASE WHEN c.id LIKE 'claim.v0230.ifa_%' THEN 'source.yoruba.ifa.unesco' WHEN c.id LIKE 'claim.v0230.sango_%' THEN 'source.yoruba.sango_festival.unesco' ELSE 'source.maori.creation.teara' END,
 'Public authority or named curated synthesis; access policy adds a precautionary project rule','OFFICIAL_SITE','SUPPORTS',c.confidence,'No restricted traditional content stored' FROM claims c WHERE c.id LIKE 'claim.v0230.%';

